class TransferFundsPayload(BaseModel):
    source_wallet_id: int
    destination_wallet_id: int
    amount: Decimal

    @field_validator("source_wallet_id")
    def validate_source(cls, v: int) -> int:
        with SessionLocal() as db:
            wallet = db.query(Wallet).filter(Wallet.id == v).first()
            if not wallet:
                raise ValueError("Source wallet does not exist")
            if wallet.is_frozen:
                raise ValueError("Source wallet is currently frozen")
        return v

@router.post("/finance/wallets/transfer")
def transfer_balance(
    payload: TransferFundsPayload,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    source = db.query(Wallet).filter(Wallet.id == payload.source_wallet_id, Wallet.owner_id == user.id).with_for_update().first()
    if not source:
        raise HTTPException(status_code=403, detail="Source wallet not found or access denied")
    if source.balance < payload.amount:
        raise HTTPException(status_code=400, detail="Insufficient funds")
    source.balance -= payload.amount
    db.commit()
    return {"status": "transfer initiated", "amount": str(payload.amount)}
